'use strict';

/**
* Immutably set a value at a path in a document using structural sharing.
*
* @module @stdlib/utils/json-patch/base/set
*
* @example
* var set = require( '@stdlib/utils/json-patch/base/set' );
*
* var doc = {
*     'a': {
*         'b': {
*             'c': 1
*         }
*     }
* };
* var out = set( doc, [ 'a', 'b', 'c' ], 99 );
* // returns { 'a': { 'b': { 'c': 99 } } }
*
* var bool = ( doc.a.b === out.a.b );
* // returns false
*
* bool = ( doc === out );
* // returns false
*/

// MODULES //

var main = require( './main.js' );


// EXPORTS //

module.exports = main;
